import React from 'react';
import { Routes, Route } from 'react-router-dom';
import LandingPage from './pages/LandingPage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import FloatingNavbar from './components/FloatingNavbar';

export default function App() {
  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans selection:bg-brand-500 selection:text-white pb-20">
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
        <Route path="/feed" element={<div className="p-8 text-center font-bold text-xl">ইমার্জেন্সি ব্লাড ফিড পেজ (Coming Soon)</div>} />
        <Route path="/search" element={<div className="p-8 text-center font-bold text-xl">জিও-সার্চ পেজ (Coming Soon)</div>} />
        <Route path="/messages" element={<div className="p-8 text-center font-bold text-xl">মেসেজিং পেজ (Coming Soon)</div>} />
        <Route path="/profile" element={<div className="p-8 text-center font-bold text-xl">ইউজার প্রোফাইল (Coming Soon)</div>} />
      </Routes>

      {/* Persistent Floating Navbar */}
      <FloatingNavbar />
    </div>
  );
}
